import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
const file=(p)=>readFileSync(p,'utf8');
const form=file('app/components/DriverRiderInterestForm.tsx');
const api=file('app/api/partners/driver-interest/route.ts');
const status=file('app/api/partners/driver-interest/status/route.ts');
const admin=file('app/api/admin/drivers/route.ts');
const earn=file('app/earn/page.tsx');
const move=file('app/move/page.tsx');
const hold=file('app/move/request/page.tsx');
const compliance=file('docs/TELANGANA_GIG_WORKER_COMPLIANCE_2026.md');
const home=file('app/components/HomeBusinessHub.tsx');
assert(form.includes('BIKE_RIDE_INTEREST'),'Interest form exposes founding Bike Ride rider interest');
assert(earn.includes('Passenger Bike Ride — founding interest only'),'Earn page prominently explains the Bike Ride founding interest path.');
assert(form.includes('interest only')&&form.includes('Do not convert your vehicle'),'Bike Ride interest is clearly not approval or permission');
assert(form.includes('Do not enter your driving-licence number, RC number, Aadhaar, PAN, bank details or OTP'),'Public interest form avoids sensitive identity/financial collection');
assert(api.includes("'BIKE_RIDE_INTEREST'"),'API accepts the new interest-only role');
assert(status.includes('bike_ride_interest_available: true'));
assert(status.includes('passenger_bike_taxi_available: false'));
assert(admin.includes("const ACTIVATABLE = new Set(['DELIVERY_RIDER','BIKE_COURIER','GOODS_DRIVER'])"));
assert(!admin.includes("'BIKE_RIDE_INTEREST'"),'Interest role must never be dispatch-activatable');
assert(move.includes('href="/earn#join"')&&move.includes('Register rider interest'));
assert(hold.includes('Register Bike Ride interest'));
assert(earn.includes('Telangana Gig Worker Programme · 2026'));
assert(earn.includes('₹5 lakh')&&earn.includes('₹10 lakh'));
assert(compliance.includes('WFFVS')&&compliance.includes('45 days'));
assert(compliance.includes('G.O.Ms.No.18')&&compliance.includes('14 days'));
assert(earn.includes('G.O.Ms.No.18'));
assert(compliance.includes('Do not hardcode a reported percentage'));
assert(home.includes('Our goal: one tree for every eligible delivered order'));
assert(home.includes('Still planning — no trees planted for orders yet.'));
console.log('PASS: Bike Ride founding interest is open, passenger activation stays blocked, Telangana gig-worker readiness is disclosed, and Zeshu Green remains honest and measurable.');
